def check_achievability(N):
    """Checks how many distinct pairs (x'+y' mod N, x'+z' mod N) can be formed
    by choosing x', y', z' uniformly from {0, ..., N-1}."""
    achieved_pairs = set()
    N_minus_1 = N - 1
    for x_prime in range(N):
        for y_prime in range(N):
            for z_prime in range(N):
                i = (x_prime + y_prime) % N
                j = (x_prime + z_prime) % N
                achieved_pairs.add((i, j))
    return len(achieved_pairs)

N_values = [3, 4]
results = {N: check_achievability(N) for N in N_values}
print(results)

